/**
 * Visual generation: turn a scene/emotion prompt into a pet asset.
 *
 * Two integration shapes, one interface:
 *   - `mock`     : deterministic 1x1 PNG, used by tests and as an offline fallback
 *   - `openai`   : any OpenAI-compatible images endpoint (`{model, prompt, size,
 *                  response_format: 'b64_json'}` → `data[0].b64_json`)
 *   - `dashscope`: 通义万相 `POST /api/v1/services/aigc/text2image/image-synthesis`
 *   - `comfyui`  : local ComfyUI `POST /prompt` (workflow template) — power users
 *
 * The generated bytes are written into `pet-assets/` by the service and served
 * read-only through `/asset/<name>`; dsh-pet plays them via `/anim` or shows
 * them as a bubble image via `/broadcast`.
 */

const MOCK_PNG = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=='

import { runWorkflow } from './comfy.js'

const withTimeout = (fn, ms) => {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), ms)
  return fn(controller.signal).finally(() => clearTimeout(timer))
}

const b64ToBuffer = (b64) => Buffer.from(String(b64 ?? ''), 'base64')

/** Generate an image and return { bytes, mime, meta }. Never writes to disk. */
export const generateImage = async ({
  prompt,
  provider = 'mock',
  endpoint = '',
  apiKey = '',
  model = '',
  size = '512x512',
  timeoutMs = 60000,
  workflow = null,
  nodeId = null,
  pollMs = 1500,
  fetchImpl = globalThis.fetch,
} = {}) => {
  const cleanPrompt = String(prompt ?? '').trim()
  if (cleanPrompt.length === 0) throw new Error('generateImage requires a prompt')
  if (provider === 'mock') {
    return { bytes: Buffer.from(MOCK_PNG, 'base64'), mime: 'image/png', meta: { provider: 'mock', prompt: cleanPrompt } }
  }

  if (provider === 'comfyui') {
    if (!endpoint) throw new Error('comfyui provider requires an endpoint (e.g. http://127.0.0.1:8188)')
    if (!workflow) throw new Error('comfyui provider requires an API-format workflow (imagegen.comfyWorkflow)')
    const result = await runWorkflow(fetchImpl, endpoint, workflow, {
      prompt: cleanPrompt,
      nodeId,
      timeoutMs: Math.max(timeoutMs, 30000),
      pollMs,
    })
    return {
      bytes: result.bytes,
      mime: result.mime,
      meta: { provider: 'comfyui', prompt: cleanPrompt, file: result.filename, ext: result.ext },
    }
  }

  if (provider === 'openai' || provider === 'siliconflow' || provider === 'generic') {
    if (!endpoint) throw new Error(`${provider} provider requires an endpoint`)
    return withTimeout(async (signal) => {
      const res = await fetchImpl(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}) },
        body: JSON.stringify({ model: model || undefined, prompt: cleanPrompt, size, n: 1, response_format: 'b64_json' }),
        signal,
      })
      if (!res.ok) throw new Error(`image endpoint ${res.status}`)
      const json = await res.json()
      const b64 = json?.data?.[0]?.b64_json ?? json?.images?.[0]?.b64_json
      if (!b64) throw new Error('image endpoint returned no b64_json')
      return { bytes: b64ToBuffer(b64), mime: 'image/png', meta: { provider, prompt: cleanPrompt } }
    }, timeoutMs)
  }

  if (provider === 'dashscope') {
    return withTimeout(async (signal) => {
      const res = await fetchImpl(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
        body: JSON.stringify({ model: model || 'wanx-v1', input: { prompt: cleanPrompt }, parameters: { size, n: 1 } }),
        signal,
      })
      if (!res.ok) throw new Error(`dashscope endpoint ${res.status}`)
      const json = await res.json()
      const url = json?.output?.results?.[0]?.url
      if (!url) throw new Error('dashscope returned no image url')
      const download = await fetchImpl(url, { signal })
      if (!download.ok) throw new Error('dashscope image download failed')
      return { bytes: Buffer.from(await download.arrayBuffer()), mime: 'image/png', meta: { provider, prompt: cleanPrompt } }
    }, timeoutMs)
  }

  throw new Error(`unknown image provider: ${provider}`)
}

/** Compose a prompt that fits the pet's visual language. */
export const buildVisualPrompt = ({ emotion = 'calm', scene = '', personality = 'curious-engineer' }) => {
  const mood = {
    joy: '开心地笑，眼睛弯弯，轻快跳跃',
    gratitude: '害羞地脸红，低头微笑，手捧心口',
    pride: '挺起胸，得意地叉腰，眼神自信',
    curiosity: '歪头，眼睛发亮，凑近观察',
    hope: '抬头看向远方，双手合十期待',
    fear: '缩成一团，耳朵压低，瑟瑟发抖',
    anxiety: '来回踱步，冒冷汗，紧张张望',
    anger: '鼓起脸，跺脚，气鼓鼓',
    guilt: '低头耷拉耳朵，内疚地道歉',
    shame: '捂脸躲闪，脸红到耳根',
    sadness: '垂头丧气，眼泪汪汪',
    frustration: '叹气，抱头，泄气',
    calm: '安静地坐着，轻轻呼吸',
    contentment: '满足地眯眼，被暖意包围',
  }[emotion] ?? '自然放松'
  return `一只 Q 版蓝发鲸鱼女仆，${mood}。${scene ? `场景：${scene}。` : ''}透明背景，扁平插画风，柔和描边，全身或半身，干净构图，适合表情包。`
}
